).TOP_K(1, by=phd_count.DESC()).CALCULATE(dept_name=dept_name)

course_with_most_students = course.WHERE(
    HAS(student_enrolment_course)
).CALCULATE(
    course_name=course_name,
    student_count=COUNT(student_enrolment_course)
).TOP_K(1, by=(student_count.DESC(), course_name.DESC()))

# Find customers who have order items with the maximum individual quantity
result = order_item.WHERE(
    order_quantity == MAX(order_item.order_quantity)
).CALCULATE(
    customer_name=customer_order.customer.customer_name
)

most_reviewed_movie = movies.WHERE(
    HAS(ratings) == 1
).CALCULATE(
    movie_title=title,
    review_count=COUNT(ratings)
).TOP_K(1, by=review_count.DESC())

most_rated_movie = movies.WHERE(
    HAS(ratings) == 1
).CALCULATE(
    rating_count=COUNT(ratings)
).TOP_K(1, by=rating_count.DESC()).CALCULATE(
    movie_title=title
)

# Find the youngest captain and get their ship's name
youngest_captain_ship = captains.CALCULATE(
    age_numeric=CAST(age, 'int')
).TOP_K(1, by=age_numeric.ASC()).CALCULATE(
    ship_name=ship.name
)

london_2018_purchases = purchases.WHERE(
    (year == "2018") & 
    (branch.city == "London")
).CALCULATE(
    total_pounds_sum = SUM(total_pounds)
)

courses_with_multiple_prereqs = courses.WHERE(
    HAS(prereqs) == 1
).PARTITION(name="course_groups", by=course_id).WHERE(
    COUNT(prereqs) > 1
).courses.CALCULATE(
    title=title,
    credits=credits,
    dept_name=dept_name
)

# Filter savings accounts to exclude those belonging to someone named "Brown" and sum their balances
total_non_brown_savings = saving.WHERE(
    ~(account.name == "Brown")
).CALCULATE(
    total_balance=SUM(balance)
)

# Filter perpetrators by height > 1.84 and calculate total kills
total_kills_result = perpetrators.WHERE(
    person.height > 1.84
).CALCULATE(
    total_kills = SUM(killed)
)

# Filter entrepreneurs by height and calculate total money requested
result = entrepreneurs.WHERE(
    person.height > 1.85
).CALCULATE(
    total_money_requested = SUM(money_requested)
)

# Calculate average max speed across all storms, then filter and aggregate
result = storm_record.CALCULATE(
    avg_max_speed = AVG(storms.max_speed)
).storms.WHERE(
    max_speed > avg_max_speed
).CALCULATE(
    total_deaths = SUM(number_deaths),
    total_damage_millions_usd = SUM(damage_millions_usd)
)

# Find colleges that do not have any goalie players and sum their enrollment
colleges_without_goalies = colleges.WHERE(
    HASNOT(tryouts.WHERE(ppos == "goalie"))
).CALCULATE(
    total_enrollment = SUM(enr)
)

# Find the total population of countries that do not use English
total_population_non_english = countries.WHERE(
    HASNOT(countrylanguages.WHERE(language == "English")) == 1
).CALCULATE(
    total_population = SUM(population)
)

# Sum total quantity of products in cancelled orders
cancelled_order_products = order_item.WHERE(
    customer_order.order_status == "Cancelled"
).CALCULATE(
    total_products=SUM(CAST(order_quantity, "int"))
)

# Find colleges that have no goalies and sum their enrollment
colleges_without_goalies = colleges.WHERE(
    HASNOT(tryouts.WHERE(ppos == "goalie")) == 1
).CALCULATE(
    total_enrollment = SUM(enr)
)

# Calculate the average city area across all districts and filter districts with above-average area
result = store_product.CALCULATE(
    avg_city_area=AVG(districts.city_area)
).districts.WHERE(
    city_area > avg_city_area
).CALCULATE(
    total_population=SUM(city_population)
)

# Filter manufacturers by headquarter location and calculate total revenue
total_revenue_result = Manufacturers.WHERE(
    (Headquarter == "Tokyo") | (Headquarter == "Taiwan")
).CALCULATE(
    total_revenue = SUM(Revenue)
)

# Find all manufacturers with revenue greater than the minimum Austin revenue and calculate total
result = manufacturer.WHERE(
    revenue > manufacturer.WHERE(headquarter == "Austin").revenue.MIN()
).CALCULATE(
    total_revenue=SUM(revenue)
)

# Find the vocal type performed most by band member with lastname "Heilo"
heilo_vocal_types = vocal.WHERE(
    band.lastname == "Heilo"
).PARTITION(
    name="vocal_types", 
    by=type
).CALCULATE(
    vocal_type=type,
    count_performances=COUNT(vocal)
).ORDER_BY(count_performances.DESC())[:1]

most_enrolled_course = course.CALCULATE(
    course_name=course_name,
    enrollment_count=COUNT(student_enrolment_course)
).TOP_K(1, by=(enrollment_count.DESC(), course_name.ASC())).CALCULATE(
    course_name=course_name
)

# Filter apartments with more than one bathroom and find the most common type
most_common_apt_type = apartment.WHERE(
    bathroom_count > 1
).PARTITION(
    name="apt_types", 
    by=apt_type_code
).CALCULATE(
    apt_type_code=apt_type_code,
    apartment_count=COUNT(apartment)
).TOP_K(1, by=apartment_count.DESC())

# Find students taught by MARROTTE KIRK
students_taught_by_marrotte_kirk = lists.WHERE(
    classroom == teacher.WHERE(
        (lastname == "MARROTTE") & (firstname == " KIRK")
    ).classroom
).CALCULATE(
    firstname=firstname,
    lastname=lastname
)

# Find attribute definitions with attribute value 0
attributes_with_zero_value = product_catalog.catalog_contents_additional_attribute.WHERE(
    attribute_value == "0"
).CALCULATE(
    attribute_id=attribute_id
).PARTITION(
    name="attr_groups", 
    by=attribute_id
).CALCULATE(
    attribute_id=attribute_id,
    attribute_name=product_catalog.attribute_definition.WHERE(
        attribute_id == attribute_id
    ).attribute_name
)

# Find catalog contents with length below 3 or width above 5
filtered_catalog_contents = catalog_content.WHERE(
    (TONUMBER(length) < 3) | (TONUMBER(width) > 5)
).CALCULATE(
    catalog_entry_name=catalog_entry_name
)

cities_with_temp_conditions = temperatures.WHERE(
    (mar < jul) | (mar > oct)
).CALCULATE(
    city_name=city.city
)

# Find the club with the most female students as members
club_with_most_females = member_of_clubs.WHERE(
    student.sex == "F"
).PARTITION(name="club_groups", by=clubid).CALCULATE(
    club_name=club.clubname,
    female_count=COUNT(member_of_clubs)
).TOP_K(1, by=female_count.DESC()).CALCULATE(
    club_name=club_name
)

# Find countries with surface area greater than any European country
result = world_1.CALCULATE(
    european_min_area = countries.WHERE(continent == "Europe").CALCULATE(
        min_area = MIN(surfacearea)
    ).SINGULAR().min_area
).countries.WHERE(
    surfacearea > european_min_area
).CALCULATE(
    country_name = name
)

# First, find the minimum dew point value in zip code 94107
min_dew_point_threshold = weathers.WHERE(zip_code == 94107).CALCULATE(
    min_threshold = MIN(min_dew_point_f)
).min_threshold

# Find all days with minimum dew point smaller than the threshold from 94107
result = bike_1.CALCULATE(
    threshold_value = min_dew_point_threshold.SINGULAR()
).weathers.WHERE(
    min_dew_point_f < threshold_value
).CALCULATE(
    date = date,
    zip_code = zip_code
).ORDER_BY(date.ASC(), zip_code.ASC())

makers_with_many_models = car_maker.WHERE(
    HAS(model_lists) == 1
).CALCULATE(
    maker_id=id,
    maker_fullname=fullname,
    model_count=COUNT(model_lists)
).WHERE(
    model_count > 3
).CALCULATE(
    fullname=maker_fullname,
    id=maker_id
)

# Find professionals who performed treatments below average cost
result = dog_kennels.professional.WHERE(
    HAS(treatment.WHERE(cost_of_treatment < RELAVG(cost_of_treatment))) == 1
).CALCULATE(
    first_name = first_name,
    last_name = last_name
).PARTITION(
    name="unique_professionals", 
    by=(first_name, last_name)
).CALCULATE(
    first_name = first_name,
    last_name = last_name
)

most_frequent_program = broadcasts.CALCULATE(
    program_name=program.name
).PARTITION(
    name="program_groups", by=program_name
).CALCULATE(
    program_name=program_name,
    broadcast_count=COUNT(broadcasts)
).TOP_K(1, by=broadcast_count.DESC()).CALCULATE(
    program_name=program_name
)

# Find the maximum dock count across all stations
max_dock_info = bike_1.CALCULATE(
    max_dock_count = MAX(stations.dock_count)
)

# Find trips that started from stations with the maximum dock count
result = max_dock_info.trips.WHERE(
    start_station_id.ISIN(
        stations.WHERE(dock_count == max_dock_count).id
    )
).CALCULATE(
    trip_id = id
)

# Find people who have friends from New York City
people_with_nyc_friends = personfriends.WHERE(
    friend IN people.WHERE(city == "new york city").name
).CALCULATE(
    person_name=name
)

employee_country_info = employees.WHERE(
    HAS(department) == 1
).department.WHERE(
    HAS(location) == 1  
).location.country.CALCULATE(
    first_name=employees.first_name,
    last_name=employees.last_name,
    employee_id=employees.employee_id,
    country_name=country_name
)

# Get employees working in departments located in London
london_employees = employee.WHERE(
    HAS(department) == 1 &
    department.location_id.ISIN(
        location.WHERE(city == "London").location_id
    )
).CALCULATE(
    full_name = JOIN_STRINGS(' ', first_name, last_name),
    employee_salary = salary
)

# Count crimes that are still under investigation
crimes_under_investigation_count = GreaterManchesterCrime.WHERE(
    Outcome == "Under investigation"
).CALCULATE(
    total_crimes_under_investigation = COUNT(CrimeID)
)

# Filter degrees for years between 1998 and 2002, join with campus info, and calculate totals by campus
total_degrees_by_campus = degree.WHERE(
    (year >= 1998) & (year <= 2002)
).CALCULATE(
    campus_name=campus_join.campus,
    total_degrees=degrees
).PARTITION(name="campus_groups", by=campus_name).CALCULATE(
    campus_name=campus_name,
    total_degrees=SUM(degree.total_degrees)
)

most_common_crime = GreaterManchesterCrime.CALCULATE(
    crime_type=type
).PARTITION(
    name="crime_groups", 
    by=crime_type
).CALCULATE(
    crime_type=crime_type,
    crime_count=COUNT(GreaterManchesterCrime)
).TOP_K(1, by=crime_count.DESC())

# Filter for prosecution cases and find crime type with most prosecutions
result = GreaterManchesterCrime.WHERE(
    outcome == 'Awaiting court outcome'
).PARTITION(
    name="crime_types", 
    by=type
).CALCULATE(
    crime_type=type,
    prosecution_count=COUNT(GreaterManchesterCrime)
).TOP_K(1, by=prosecution_count.DESC())
